/**
 * Unit tests for ShapeUtilities.equal(GeneralPath, GeneralPath).
 * Note: The provided source code contains a 'if (true) { return false; }' 
 * which makes the method logically always return false if p1 and p2 are non-null.
 */
public class ShapeUtilities_equal_TriageGen0Test {

    @Test
    public void testEqual_BothNull() {
        assertTrue(ShapeUtilities.equal(null, null));
    }

    @Test
    public void testEqual_P1Null_P2NotNull() {
        GeneralPath p2 = new GeneralPath();
        assertFalse(ShapeUtilities.equal(null, p2));
    }

    @Test
    public void testEqual_P1NotNull_P2Null() {
        GeneralPath p1 = new GeneralPath();
        assertFalse(ShapeUtilities.equal(p1, null));
    }

    @Test
    public void testEqual_DifferentWindingRules() {
        GeneralPath p1 = new GeneralPath(GeneralPath.WIND_EVEN_ODD);
        GeneralPath p2 = new GeneralPath(GeneralPath.WIND_NON_ZERO);
        assertFalse(ShapeUtilities.equal(p1, p2));
    }

    @Test
    public void testEqual_SameWindingRule_TriggersBuggyReturn() {
        // This test covers the branch where p1 and p2 are non-null, 
        // have same winding rule, and the loop logic.
        // Given the 'if (true) { return false; }' in the source, 
        // any non-null paths will result in false.
        GeneralPath p1 = new GeneralPath();
        p1.moveTo(0, 0);

        GeneralPath p2 = new GeneralPath();
        p2.moveTo(0, 0);

        // Since the code has an explicit 'if (true) return false', 
        // it will return false here.
        assertFalse(ShapeUtilities.equal(p1, p2));
    }

    @Test
    public void testEqual_DifferentPathLengths() {
        // This tests the 'if (iterator1.isDone() != iterator2.isDone())' branch.
        // However, due to the 'if (true)' block, we can only reach this if 
        // the iterator logic is bypassed or if we assume the 'if (true)' is a placeholder.
        // Based strictly on the provided code, the 'if (true)' prevents reaching the rest.

        GeneralPath p1 = new GeneralPath();
        p1.moveTo(0, 0);

        GeneralPath p2 = new GeneralPath();
        // p2 is empty, so iterator1.isDone() will be false (it has a segment) 
        // and iterator2.isDone() will be true.

        // But wait, the 'while(!done)' loop condition and the 'if (true)' 
        // mean we hit 'return false' immediately on the first segment.
        assertFalse(ShapeUtilities.equal(p1, p2));
    }
}
